import pandas as pd
from collections import deque


def run(inputs: dict) -> dict:
    trades = inputs["trades"].copy()

    trades = trades.sort_values(
        by=["account_id", "symbol", "trade_ts", "trade_id"],
        kind="mergesort"
    )

    sell_rows = []
    open_rows = []

    for (acct, sym), grp in trades.groupby(["account_id", "symbol"], sort=False):
        lots = deque()  # each element: [lot_trade_id, remaining_qty, price]

        for _, row in grp.iterrows():
            side = row["side"]
            if side == "BUY":
                lots.append([row["trade_id"], row["qty"], row["price"]])
            elif side == "SELL":
                still_to_sell = row["qty"]
                matched = 0
                pnl = 0.0

                while still_to_sell > 0 and lots and lots[0][1] > 0:
                    lot = lots[0]
                    take = min(lot[1], still_to_sell)
                    pnl += take * (row["price"] - lot[2])
                    lot[1] -= take
                    matched += take
                    still_to_sell -= take
                    if lot[1] == 0:
                        lots.popleft()

                short = row["qty"] - matched

                sell_rows.append({
                    "trade_id": row["trade_id"],
                    "matched_qty": matched,
                    "short_qty": short,
                    "realized_pnl": pnl
                })
            # any other side value is ignored (not BUY/SELL)

        for lot in lots:
            if lot[1] > 0:
                open_rows.append({
                    "lot_trade_id": lot[0],
                    "account_id": acct,
                    "symbol": sym,
                    "remaining_qty": lot[1],
                    "price": lot[2]
                })

    sell_results = pd.DataFrame(
        sell_rows,
        columns=["trade_id", "matched_qty", "short_qty", "realized_pnl"]
    )
    if len(sell_results) > 0:
        sell_results["trade_id"] = sell_results["trade_id"].astype("int64")
        sell_results["matched_qty"] = sell_results["matched_qty"].astype("int64")
        sell_results["short_qty"] = sell_results["short_qty"].astype("int64")
        sell_results["realized_pnl"] = sell_results["realized_pnl"].astype("float64")
    else:
        sell_results = pd.DataFrame({
            "trade_id": pd.Series(dtype="int64"),
            "matched_qty": pd.Series(dtype="int64"),
            "short_qty": pd.Series(dtype="int64"),
            "realized_pnl": pd.Series(dtype="float64"),
        })

    open_lots = pd.DataFrame(
        open_rows,
        columns=["lot_trade_id", "account_id", "symbol", "remaining_qty", "price"]
    )
    if len(open_lots) > 0:
        open_lots["lot_trade_id"] = open_lots["lot_trade_id"].astype("int64")
        open_lots["account_id"] = open_lots["account_id"].astype("int64")
        open_lots["symbol"] = open_lots["symbol"].astype(str)
        open_lots["remaining_qty"] = open_lots["remaining_qty"].astype("int64")
        open_lots["price"] = open_lots["price"].astype("float64")
    else:
        open_lots = pd.DataFrame({
            "lot_trade_id": pd.Series(dtype="int64"),
            "account_id": pd.Series(dtype="int64"),
            "symbol": pd.Series(dtype="object"),
            "remaining_qty": pd.Series(dtype="int64"),
            "price": pd.Series(dtype="float64"),
        })

    return {"sell_results": sell_results, "open_lots": open_lots}
